const { useState } = React;

function App() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [errors, setErrors] = useState({});

  function validate() {
    const newErrors = {};
    if (!email) {
      newErrors.email = "Email is required.";
    } else if (!/^\S+@\S+\.\S+$/.test(email)) {
      newErrors.email = "Email is invalid.";
    }
    if (!password) {
      newErrors.password = "Password is required.";
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  }

  function handleSubmit(e) {
    e.preventDefault();
    if (validate()) {
      alert(`Logging in with Email: ${email}`);
    }
  }

  return (
    <>
      <style>{`
        * {
          box-sizing: border-box;
        }
        body,html,#root {
          margin: 0;
          height: 100%;
          font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
          background: #fff;
          color: #222;
        }
        main {
          height: 100%;
          display: flex;
          justify-content: center;
          align-items: center;
          padding: 20px;
        }
        form {
          width: 320px;
          display: flex;
          flex-direction: column;
          gap: 12px;
        }
        h2 {
          text-align: center;
          font-weight: 400;
          margin-bottom: 12px;
          font-size: 1.5rem;
          color: #222;
        }
        .image-placeholder {
          width: 100%;
          height: 140px;
          border: 2px solid #222;
          border-radius: 6px;
          position: relative;
          margin-bottom: 16px;
        }
        .image-placeholder:before, .image-placeholder:after {
          content: '';
          position: absolute;
          border: 2px solid #222;
          top: 0;
          bottom: 0;
          left: 0;
          right: 0;
          border-radius: 6px;
        }
        .image-placeholder:before {
          transform: rotate(45deg);
          border-color: #222;
        }
        .image-placeholder:after {
          transform: rotate(-45deg);
          border-color: #222;
        }
        label {
          font-size: 0.9rem;
          margin-bottom: 4px;
          color: #444;
        }
        input {
          padding: 10px 12px;
          font-size: 1rem;
          border: 2px solid #222;
          border-radius: 6px;
          outline-offset: 2px;
          outline-color: transparent;
          transition: outline-color 0.2s ease;
        }
        input:focus {
          outline-color: #0078d4;
          border-color: #0078d4;
        }
        .error {
          color: #d93025;
          font-size: 0.8rem;
          margin-top: 2px;
        }
        button {
          margin-top: 12px;
          padding: 16px 0;
          font-size: 1.3rem;
          border-radius: 9999px;
          border: 2px solid #222;
          background: #fff;
          cursor: pointer;
          transition: background-color 0.3s ease, color 0.3s ease;
          font-family: inherit;
        }
        button:hover {
          background-color: #222;
          color: #fff;
          border-color: #222;
        }
      `}</style>
      <main>
        <form onSubmit={handleSubmit} noValidate>
          <h2>Login</h2>
          <div className="image-placeholder" aria-hidden="true"></div>

          <label htmlFor="email">Email</label>
          <input
            id="email"
            type="email"
            value={email}
            onChange={e => setEmail(e.target.value)}
            aria-describedby={errors.email ? "email-error" : undefined}
            aria-invalid={errors.email ? "true" : "false"}
            placeholder="Email"
          />
          {errors.email && <p id="email-error" role="alert" className="error">{errors.email}</p>}

          <label htmlFor="password">Password</label>
          <input
            id="password"
            type="password"
            value={password}
            onChange={e => setPassword(e.target.value)}
            aria-describedby={errors.password ? "password-error" : undefined}
            aria-invalid={errors.password ? "true" : "false"}
            placeholder="Password"
          />
          {errors.password && <p id="password-error" role="alert" className="error">{errors.password}</p>}

          <button type="submit">Login</button>
        </form>
      </main>
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

